return ['domain'=>'zinn-cache','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'zinn-cache','pot-creation-date'=>'2026-09-02T07:33:02+00:00','po-revision-date'=>'2026-09-02T07:33:02+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache'=>'Zinn® Cache','https://zinndigital.com/wordpress-plugins/zinn-cache'=>'https://zinndigital.com/wordpress-plugins/zinn-cache','For sites hosted with Zinn Digital®. Controls the page cache your Zinn® server already provides — smart auto-purge on content change, remote purge from your Zinn® dashboard, a Redis object-cache toggle, safe WordPress/WooCommerce exclusions, and one-click admin login. This is a cache controller, not a cache engine. Hosting elsewhere? Install Zinn® Cache Engine instead.'=>'Za sajtove koji se hostuju na Zinn Digital®. Upravlja kešom stranica koji vaš Zinn® server već obezbeđuje — pametno automatsko čišćenje pri izmeni sadržaja, udaljeno čišćenje sa vaše Zinn® kontrolne table, preklopnik za Redis keš objekata, bezbedna izuzeća za WordPress/WooCommerce i prijava u administraciju jednim klikom. Ovo je kontrolor keša, a ne mašina za keširanje. Hostujete negde drugde? Umesto toga instalirajte Zinn® Cache Engine.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','You are not allowed to purge the cache.'=>'Nije vam dozvoljeno da ispraznite keš.','Cache purge requested.'=>'Zatraženo je pražnjenje keša.','Zinn® Cache: another object-cache drop-in is installed, so the Redis object cache is not managed by this plugin.'=>'Zinn® Cache: instaliran je drugi dodatak za keširanje objekata, tako da Redis keš objekata nije pod upravom ovog dodatka.','Full-page cache (LiteSpeed)'=>'Keš cele stranice (LiteSpeed)','Enable LSCache control'=>'Omogući LSCache kontrolu','Send LiteSpeed cache-control and tag headers on cacheable pages.'=>'Šalji LiteSpeed cache-control i tag zaglavlja na stranicama koje se mogu keširati.','Public cache lifetime (seconds)'=>'Trajanje javnog keša (sekunde)','Object cache (Redis)'=>'Keš objekata (Redis)','Enable Redis object cache'=>'Omogući Redis keš objekata','Install the Redis object-cache drop-in (requires the phpredis extension).'=>'Instaliraj drop-in za Redis keš objekata (zahteva phpredis ekstenziju).','Redis host'=>'Redis host','Redis port'=>'Redis port','Redis database'=>'Redis baza podataka','Redis key prefix'=>'Prefiks Redis ključa','Automatic purging'=>'Automatsko pražnjenje','Smart auto-purge'=>'Pametno automatsko pražnjenje','Purge affected pages automatically when content changes.'=>'Automatski isprazni pogođene stranice kada se sadržaj promeni.','Purge on updates'=>'Isprazni pri ažuriranjima','Purge everything after core, plugin, or theme updates.'=>'Isprazni sve nakon ažuriranja jezgra, dodataka ili tema.','Cache exclusions'=>'Izuzeci keša','Sensible WordPress and WooCommerce defaults are always applied (cart, checkout, my-account, logged-in and session pages are never cached). Add extra rules below, one per line.'=>'Razumne podrazumevane vrednosti za WordPress i WooCommerce se uvek primenjuju (korpa, naplata, moj-nalog, prijavljene i sesijske stranice se nikada ne keširaju). Dodajte dodatna pravila ispod, po jedno u redu.','Exclude URL paths (prefix match)'=>'Izuzmi URL putanje (poklapanje prefiksa)','Exclude query keys'=>'Izuzmi ključeve upita','Exclude cookie name prefixes'=>'Izuzmi prefikse imena kolačića','Maintenance'=>'Održavanje','Purge everything now'=>'Isprazni sve odmah','detected'=>'otkriveno','not detected'=>'nije otkriveno','phpredis extension missing'=>'phpredis ekstenzija nedostaje','active'=>'aktivno','inactive'=>'neaktivno','LiteSpeed cache:'=>'LiteSpeed keš:','Redis object cache:'=>'Redis keš objekata:','The Redis PHP extension (phpredis) is not available on this server, so the object cache cannot be enabled.'=>'Redis 